import type { FeedConfig, FeedItem, ScraperHelpers } from "@rss-agentic/core"

/**
 * Convert Markdown list content to HTML.
 * Handles: bullet lists, **bold**, `code`, [links](url)
 */
function mdToHtml(body: string[]): string {
  const htmlParts: string[] = []
  let inList = false

  for (const line of body) {
    const trimmed = line.trim()
    if (trimmed === '') {
      if (inList) {
        htmlParts.push('</ul>')
        inList = false
      }
      continue
    }

    // Bullet list item
    const listMatch = trimmed.match(/^-\s+(.+)/)
    if (listMatch) {
      if (!inList) {
        htmlParts.push('<ul>')
        inList = true
      }
      let content = listMatch[1]
      content = content
        .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
        .replace(/`([^`]+)`/g, '<code>$1</code>')
        .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>')
      htmlParts.push(`  <li>${content}</li>`)
    } else {
      // Non-list line – treat as paragraph
      if (inList) {
        htmlParts.push('</ul>')
        inList = false
      }
      let content = trimmed
      content = content
        .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
        .replace(/`([^`]+)`/g, '<code>$1</code>')
        .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>')
      htmlParts.push(`<p>${content}</p>`)
    }
  }

  if (inList) {
    htmlParts.push('</ul>')
  }

  return htmlParts.join('\n')
}

/**
 * Create a GitHub anchor ID from a heading text.
 * GitHub lowercases, removes most special chars, replaces spaces with hyphens.
 */
function githubAnchor(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9\- ]/g, '') // remove non-alphanumeric except hyphens/spaces
    .replace(/\s+/g, '-')          // spaces → hyphens
    .replace(/-+/g, '-')           // collapse multiple hyphens
    .replace(/^-|-$/g, '')         // trim leading/trailing hyphens
}

/**
 * Parse a semver version number to a sortable integer for ordering.
 */
function versionOrdinal(version: string): number {
  const parts = version.split('.').map(Number)
  return parts[0] * 1000000 + (parts[1] || 0) * 1000 + (parts[2] || 0)
}

export async function fetchFeed(config: FeedConfig, helpers: ScraperHelpers): Promise<FeedItem[]> {
  const resp = await fetch(config.url)
  const text = await resp.text()

  const lines = text.split('\n')
  const sections: { version: string; body: string[] }[] = []
  let current: { version: string; body: string[] } | null = null

  for (const line of lines) {
    const headerMatch = line.match(/^##\s+(.+)$/)
    if (headerMatch) {
      if (current) sections.push(current)
      current = { version: headerMatch[1].trim(), body: [] }
    } else if (current) {
      current.body.push(line)
    }
  }
  if (current) sections.push(current)

  // Filter to only version-like sections (semver pattern)
  const versionSections = sections.filter(s =>
    /^\d+\.\d+\.\d+/.test(s.version)
  )

  const now = new Date().toISOString()
  const baseUrl = 'https://github.com/anthropics/claude-code/blob/main/CHANGELOG.md'

  const items: FeedItem[] = versionSections.map((s) => {
    const anchor = githubAnchor(s.version)
    const itemUrl = `${baseUrl}#${anchor}`
    const contentHtml = mdToHtml(s.body)

    return {
      id: `claude-code-v${s.version}`,
      title: `Version ${s.version}`,
      url: itemUrl,
      publishedAt: now,
      source: config.slug,
      contentHtml,
    }
  })

  // Sort descending by version (newest first)
  items.sort((a, b) => {
    const vA = a.id.replace('claude-code-v', '')
    const vB = b.id.replace('claude-code-v', '')
    return versionOrdinal(vB) - versionOrdinal(vA)
  })

  return items
}
